#!/bin/bash
# shellcheck disable=SC2015
set -eEuo pipefail
# usvKacheln. Nummer bewusst offen, nicht commit65.
# Nur die USV-EG-Anzeige. Pinneberg Stufe 1 bleibt. Kein Tunnel, kein apt, kein prepper-sdr.
# Aufruf: bash apply-usv-eg.sh usvKacheln [dry-run]
# Simulation: DASH_PORT=5093 C61_SIM_DIR C61_SIM_W C61_FAKE_HM C61_RETRY_S C61_WAIT_S C61_SIM_NOMUT C61_READY_S
COMMIT_ARG="${1:-unbekannt}"
MODE_ARG="${2:-}"
case "$COMMIT_ARG" in
  usvKacheln) ;;
  commit65|65) echo "STOP: commit65 bleibt frei. Dieser Lauf heisst usvKacheln. Nichts geaendert"; exit 1;;
  *) echo "STOP: erster Parameter muss usvKacheln sein (war '$COMMIT_ARG'). Nichts geaendert"; exit 1;;
esac
case "$MODE_ARG" in ""|dry-run|--dry-run|dryrun|trockenlauf) ;; *) echo "STOP: unbekannter zweiter Parameter '$MODE_ARG' (erlaubt: dry-run) - nichts geaendert"; exit 1;; esac
DRY=0; [[ -n "$MODE_ARG" ]] && DRY=1
DASH_DIR="/home/fmg/prepper-dashboard"
W=/tmp/usvkachel-apply
NM=usvkachel
MK=usvKacheln
SIM=0; [[ -n "${DASH_PORT:-}" && "${DASH_PORT:-}" != 5000 ]] && SIM=1
if [[ "$SIM" == 1 ]]; then DASH_DIR="${C61_SIM_DIR:-$DASH_DIR}"; W="${C61_SIM_W:-$W}"; fi
VPY="$DASH_DIR/venv/bin/python"
SPY=/usr/bin/python3
TS=$(date +%Y%m%d-%H%M%S)
KEEP_LAST=3
declare -A ALT=(
  [ups_manager.py]=4a28a09242bc9b40eb655a3a61e446ed75407736a24670c2647f506cea9b80cb
  [lage_pages.py]=8ac12d053ccc3ed9d6ed7dcff7772a6ef62821736d581513560461b00d3dbb38
  [prepper_docs.py]=8fcc17daf1b3d4d2549aad3e4523b16bd60f4a679ad5c6db5f3c40d6199ba105
)
declare -A NEU=(
  [ups_manager.py]=d670aca41895559c2aa5c46dc6432cdba78b60b2c69720e4482e2b16b45f55dd
  [lage_pages.py]=27c72615609e2ef11ade38d9dd5a681505c992e4dba4904badc4fb793f81b748
  [prepper_docs.py]=38aff52eae6bfbdf5aa572905c8ee18e492cf5a3c0a1726504422e24f3d751d4
)
LAGE_FULL=d268d324f4fd55a53cb7ee1919e3fb399e2c4ca0a7733780c9bf977b0fee2fca
LAGE_GIT=f85f24fd0ef8189cfd818eaf2dfaa0173f46bd6efbde516ce28a569eaa64ffa0
DASH_KEEP=6d9fe2860fc636713461fd22b78de03941e23d167b7475e608f773fd0e5650b9
SDR_KEEP=533b6f9db8da0bcb73ca0e956bfc7a2edfade287375aa4eaf21f10a4ab37fb32
ROLLE_KEEP=981cacdbf5a81348f9b32f67ac1c9ca27382af916d340c3b7773a84e87df06f5
JSON_KEEP=e091123291a188749e7f6ea28f72672ae3bc314120a45bb5da8ed0fa08e58e8f
declare -A KEEP=(
  [gas_saison.py]=1a258f195e59528b23841e350fdf505959d461f7779c7969ef0264980ee875d4
  [sdr_manager.py]=5a26efff608bf541
  [database.py]=2754d0bdddca9400
  [prepper_evlog.py]=8bffd396972b60fa
)
PHASE=vorher
FINISHED=0
RESTARTED=0
STOPPED=0
RB_DONE=0
INST=()
LH0=""
ERRLN=""; ERRCMD=""
trap 'ERRLN=$LINENO; ERRCMD=$BASH_COMMAND' ERR
stop() { STOPPED=1; echo "STOP: $1 - nichts geaendert"; exit 1; }
CFG_PORT=$(sed -n 's/^PORT[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p' "$DASH_DIR/config.py" 2>/dev/null | head -1 || true)
PORT="${DASH_PORT:-${CFG_PORT:-5000}}"
if ! [[ "$PORT" =~ ^[0-9]+$ ]]; then stop "Dashboard-Port unklar ($PORT)"; fi
if [[ "$PORT" == "8080" ]]; then stop "Port 8080 ist kiwix-serve, nicht das Dashboard"; fi
if [[ "$SIM" == 1 && "$PORT" != "5093" ]]; then stop "Simulation nur auf Port 5093 (jetzt $PORT)"; fi
if [[ "$SIM" == 0 && "$PORT" != "5000" ]]; then stop "Echter Lauf nur auf Port 5000 (jetzt $PORT)"; fi
B="http://127.0.0.1:${PORT}"
CURL=(curl --compressed -s --connect-timeout 3 --max-time 40)
[[ -x "$SPY" ]] || stop "System-Python $SPY fehlt oder ist nicht ausfuehrbar"
if [[ ! -x "$VPY" ]]; then stop "Dashboard-venv $VPY fehlt oder ist nicht ausfuehrbar. Kein Rueckfall auf das System-Python."; fi
if ! "$VPY" -c 'import flask,sys; assert sys.version_info>=(3,9); assert sys.prefix!=sys.base_prefix, sys.prefix'; then
  stop "Dashboard-venv $VPY laedt Flask nicht oder ist kein eigenes venv. Nichts wird nachinstalliert und nichts auf $SPY umgebogen."
fi
if PYTHONNOUSERSITE=1 "$SPY" -c 'import flask' >/dev/null 2>&1; then
  stop "System-Python $SPY kann Flask importieren. Die getrennte Pruefung waere damit nicht echt."
fi
for t in python3 sha256sum curl flock cp mv cmp stat date timeout nice base64; do command -v "$t" >/dev/null 2>&1 || stop "Werkzeug $t fehlt"; done
s16() { sha256sum "$1" | cut -c1-16; }
sfull() { sha256sum "$1" | cut -d' ' -f1; }
on_exit() {
  local ec=$?
  if [[ $ec -ne 0 && $FINISHED -eq 0 ]]; then
    if [[ "$PHASE" == vorher ]]; then
      [[ -n "$ERRLN" && "$STOPPED" == 0 ]] && echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile $ERRLN, Befehl: $(echo "$ERRCMD" | cut -c1-400) - es wurde noch nichts geaendert"
    elif [[ "$PHASE" == installiert && "$RB_DONE" == 0 ]]; then
      echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile ${ERRLN:-?}, Befehl: $(echo "${ERRCMD:-?}" | cut -c1-400) - Rollback"
      rb "unerwarteter Fehler" || true
    fi
  fi
}
trap on_exit EXIT
echo "=== $MK ($COMMIT_ARG$([[ "$DRY" == 1 ]] && echo ", TROCKENLAUF")): USV EG nur lesen, Port $PORT, Ordner $DASH_DIR ==="
echo "Nummer offen, nicht commit65. Kein apt, kein Tunnel, prepper-sdr wird nicht neu gestartet. Pinneberg bleibt Stufe 1."
umask 022
mkdir -p "$(dirname "$W")"
exec 9>"$W.lock"
flock -n 9 || stop "ein anderer $NM-Lauf ist aktiv (Sperre $W.lock)"
rm -rf "$W" && mkdir -p "$W/neu" "$W/alt" "$W/html" && chmod 700 "$W"
python3 - "$W/neu" << 'MK_PAY_EOF'
import base64, hashlib, os, sys
dest = sys.argv[1]
os.makedirs(dest, exist_ok=True)
raw = {
    'ups_manager.py': '',
    'lage_pages.py': '',
    'prepper_docs.py': '',
}
expect = {
    'ups_manager.py': 'd670aca41895559c2aa5c46dc6432cdba78b60b2c69720e4482e2b16b45f55dd',
    'lage_pages.py': '27c72615609e2ef11ade38d9dd5a681505c992e4dba4904badc4fb793f81b748',
    'prepper_docs.py': '38aff52eae6bfbdf5aa572905c8ee18e492cf5a3c0a1726504422e24f3d751d4',
}
for name, b64 in raw.items():
    data = base64.b64decode(b64)
    got = hashlib.sha256(data).hexdigest()
    if got != expect[name]:
        sys.stderr.write("FEHLER sha256 %s %s\n" % (name, got))
        sys.exit(1)
    tmp = os.path.join(dest, name + ".tmp")
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, os.path.join(dest, name))
print("OK Nutzlast sha256 geprueft (%d Dateien)" % len(raw))
MK_PAY_EOF
EXPECT_GRD='be47277f7beaf753400485d00ec2babbf02eadd6d40bd344ac1368f676a29ca1'
cat > "$W/guard.py" << 'MK_GRD_EOF'
#!/usr/bin/env python3
"""guard usvKacheln. Prueft die nur lesende EG-Anzeige und laesst Stufe 1 unangetastet."""
import sys

SHUT = "Abschaltung bei 20 % oder 5 min · upsmon aktiv"


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def chk(files):
    err = []
    ups, lage, docs = files["ups_manager.py"], files["lage_pages.py"], files["prepper_docs.py"]
    dash, pn, sdr = files["dashboard.py"], files["pinneberg_rolle.py"], files["prepper_sdr.py"]
    if 'HOST = "127.0.0.1"' not in ups or "if host != HOST:" not in ups:
        err.append("Host ist nicht nur Loopback")
    if "port == PORT_DEFAULT" not in ups:
        err.append("EG liest die lokale USV")
    if 'd.get("enabled") is not True' not in ups:
        err.append("Einschalten ist kein Wahrheitswert")
    if 'sendall(("LIST %s\\n" % what)' not in ups:
        err.append("Protokoll ist nicht nur LIST")
    if "r = dict(EG_SOH)" not in ups:
        err.append("SoH wird aus der Ladung")
    if 'EG_AKKU_EINBAU = "2026-05"' not in ups or 'AKKU_EINBAU = "2026-05"' not in ups:
        err.append("Einbau ist nicht 05.2026")
    if "keine Abschaltung · nur Anzeige" not in ups or "Abschaltung bei 20 %" in ups:
        err.append("EG uebernimmt die Abschaltung")
    if "pinneberg" in ups.lower():
        err.append("Vermischung mit Pinneberg")
    if "192.168.178.3" in lage or "192.168.178.3" in docs:
        err.append("unbestaetigte Adresse steht in der Anzeige")
    if 'id="usvEg"' not in lage or "function eg(d)" not in lage or "nicht SoH" not in lage:
        err.append("EG-Kachel zeigt keine getrennte Messung")
    for need in ("usvEgMain", "usvEgBar", "usvEgSoh", "usvEgTest", "usvEgAlarm", "usvEgShut", "05.2026"):
        if need not in lage:
            err.append("EG-Zeile fehlt: " + need)
    card = lage.split('id="usvEg"', 1)[-1].split("/* usvKachel */", 1)[0]
    if "upsmon" in card or "20 %" in card:
        err.append("EG-Kachel uebernimmt die Abschaltung")
    if 'get("scenario_note")' in lage or 'get("profile_text")' in lage:
        err.append("Speicher-Kuerzung wurde rueckgaengig gemacht")
    if "usvKacheln" not in docs or "127.0.0.1:3494" not in docs:
        err.append("Doku ohne Tunnel")
    if "pinnebergRolle" not in docs or "stimmeDe" not in docs:
        err.append("Rolle oder Stimme fehlt in der Beschreibung")
    if "USVA_LOW_S = 300" not in dash or dash.count(SHUT) != 3:
        err.append("USV-Schwelle geaendert")
    if "STUFE = 1" not in pn or "RF_HZ = 147300" not in pn:
        err.append("Pinneberg-Stufe veraendert")
    want = sdr.split("def _pn_want", 1)[-1].split("def _pn_bc_queue", 1)[0]
    if "_pn.engaged" not in want or 'return "idle"' not in want:
        err.append("Stick-3-Reservierung fehlt")
    return err


def main():
    if len(sys.argv) < 3:
        print("Aufruf: guard.py check|mutate NEU")
        sys.exit(2)
    cmd, neu = sys.argv[1], sys.argv[2]
    names = ("ups_manager.py", "lage_pages.py", "prepper_docs.py", "dashboard.py", "pinneberg_rolle.py", "prepper_sdr.py")
    files = {n: read("%s/%s" % (neu, n)) for n in names}
    if cmd == "check":
        e = chk(files)
        if e:
            print("\n".join("VERSTOSS " + x for x in e))
            sys.exit(1)
        print("Guard usvKacheln ok: nur Lesen, Tunnel aus, Stufe 1 bleibt, Kuerzung bleibt")
        return
    ups, lage, dash, pn, sdr = (files[n] for n in ("ups_manager.py", "lage_pages.py", "dashboard.py", "pinneberg_rolle.py", "prepper_sdr.py"))

    def put(**kw):
        out = dict(files)
        out.update(kw)
        return out

    mut = [
        ("Host 0.0.0.0", put(**{"ups_manager.py": ups.replace('HOST = "127.0.0.1"', 'HOST = "0.0.0.0"', 1)})),
        ("fremder Host", put(**{"ups_manager.py": ups.replace("if host != HOST:", "if False and host != HOST:", 1)})),
        ("EG auf Port 3493", put(**{"ups_manager.py": ups.replace("port == PORT_DEFAULT", "port == -1", 1)})),
        ("Einschalten als Text", put(**{"ups_manager.py": ups.replace('d.get("enabled") is not True', 'd.get("enabled") not in (True, "true")', 1)})),
        ("Schreibbefehl", put(**{"ups_manager.py": ups.replace('sendall(("LIST %s\\n" % what)', 'sendall(("INSTCMD %s\\n" % what)', 1)})),
        ("Ladung wird SoH", put(**{"ups_manager.py": ups.replace("r = dict(EG_SOH)", 'r = {"state": "GUT", "pct": 100, "txt": "ladung", "basis": None}', 1)})),
        ("EG-Einbau falsch", put(**{"ups_manager.py": ups.replace('EG_AKKU_EINBAU = "2026-05"', 'EG_AKKU_EINBAU = "2024-01"', 1)})),
        ("EG-Abschaltung kopiert", put(**{"ups_manager.py": ups.replace("keine Abschaltung · nur Anzeige", "Abschaltung bei 20 % oder 5 min · upsmon aktiv", 1)})),
        ("Kuerzung zurueck", put(**{"lage_pages.py": lage + '\nget("scenario_note")\nget("profile_text")\n'})),
        ("Abschaltschwelle", put(**{"dashboard.py": dash.replace("USVA_LOW_S = 300", "USVA_LOW_S = 60", 1)})),
        ("Abschalttext weg", put(**{"dashboard.py": dash.replace(SHUT, "Abschaltung aus", 1)})),
        ("Pinneberg Stufe 2", put(**{"pinneberg_rolle.py": pn.replace("STUFE = 1", "STUFE = 2", 1)})),
        ("Stick 3 bleibt auf Sendung", put(**{"prepper_sdr.py": sdr.replace('if _s3e_is_h2(self) and _pn.engaged(getattr(self, "base", None)):\n            return "idle"', "if False:\n            return \"idle\"", 1)})),
    ]
    bad = 0
    for name, changed in mut:
        e = chk(changed)
        print(("erkannt  " if e else "UEBERSEHEN ") + name + ((": " + e[0]) if e else ""))
        if not e:
            bad += 1
    print("Mutationstest usvKacheln: %d/%d erkannt" % (len(mut) - bad, len(mut)))
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
MK_GRD_EOF
echo "$EXPECT_GRD  $W/guard.py" | sha256sum -c - >/dev/null 2>&1 || stop "sha256 von guard.py falsch (Skript beschaedigt oder veraendert - bitte neu laden)"
echo "OK eingebettete Nutzlast und Guard geprueft"
SINGLE=(ups_manager.py lage_pages.py prepper_docs.py)
for f in "${SINGLE[@]}" dashboard.py prepper_sdr.py pinneberg_rolle.py pinneberg_rolle.json "${!KEEP[@]}"; do
  [[ -f "$DASH_DIR/$f" ]] || stop "$f fehlt im Projektordner $DASH_DIR"
done
NA=0; NN=0; ODD=""
for f in "${SINGLE[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$h" == "${ALT[$f]}" ]]; then NA=$((NA+1))
  elif [[ "$h" == "${NEU[$f]}" ]]; then NN=$((NN+1))
  elif [[ "$f" == lage_pages.py && "$h" == "$LAGE_FULL" ]]; then stop "lage_pages.py ist die ungekurzte Fassung ${h:0:16}. Die installierte Basis ist die Kuerzung ${ALT[lage_pages.py]:0:16}."
  elif [[ "$f" == lage_pages.py && "$h" == "$LAGE_GIT" ]]; then stop "lage_pages.py ist die Review-Fassung mit den Gaszeilen ${h:0:16}. Auf dem Prepper liegt die Kuerzung ${ALT[lage_pages.py]:0:16}."
  else ODD+="$f=${h:0:16} "; fi
done
[[ -z "$ODD" ]] || stop "Stand weicht ab (usvKacheln setzt die installierte Pinneberg-Stufe 1 voraus): ${ODD}"
DH=$(sfull "$DASH_DIR/dashboard.py"); [[ "$DH" == "$DASH_KEEP" ]] || stop "dashboard.py ${DH:0:16} ist nicht die installierte Stufe 1 (${DASH_KEEP:0:16})"
SH=$(sfull "$DASH_DIR/prepper_sdr.py"); [[ "$SH" == "$SDR_KEEP" ]] || stop "prepper_sdr.py ${SH:0:16} ist nicht die installierte Stufe 1"
RH=$(sfull "$DASH_DIR/pinneberg_rolle.py"); [[ "$RH" == "$ROLLE_KEEP" ]] || stop "pinneberg_rolle.py ${RH:0:16} ist nicht Stufe 1"
JH=$(sfull "$DASH_DIR/pinneberg_rolle.json"); [[ "$JH" == "$JSON_KEEP" ]] || stop "pinneberg_rolle.json ${JH:0:16} ist nicht die installierte Rolle"
KODD=""
for f in "${!KEEP[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$f" == gas_saison.py ]]; then [[ "$h" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "
  else [[ "${h:0:16}" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "; fi
done
[[ -z "$KODD" ]] || stop "Unveraenderte Dateien weichen ab: ${KODD}"
if [[ "$NA" == 3 ]]; then STATE=alt; echo "OK Basis ist die installierte Stufe 1, lage_pages die Kuerzung"
elif [[ "$NN" == 3 ]]; then STATE=neu; echo "OK $MK ist schon installiert"
else
  echo "STOP: Mischstand - nichts geaendert."
  for f in "${SINGLE[@]}"; do echo "      $f $(sfull "$DASH_DIR/$f" | cut -c1-16)"; done
  STOPPED=1; exit 1
fi
LH0=$(sfull "$DASH_DIR/lage_pages.py")
[[ -w "$DASH_DIR" ]] || stop "Projektordner nicht beschreibbar"
mkdir -p "$W/check"
cp "$W/neu/ups_manager.py" "$W/neu/lage_pages.py" "$W/neu/prepper_docs.py" "$W/check/"
cp "$DASH_DIR/dashboard.py" "$DASH_DIR/pinneberg_rolle.py" "$DASH_DIR/prepper_sdr.py" "$W/check/"
python3 "$W/guard.py" check "$W/check" > "$W/g.log" 2>&1 || { cat "$W/g.log"; stop "Guard $MK meldet Verstoss"; }
echo "OK $(head -1 "$W/g.log")"
MUTS=1; [[ -n "${C61_SIM_NOMUT:-}" && "$SIM" == 1 ]] && { MUTS=0; echo "SIM: Mutationstest uebersprungen"; }
if [[ "$MUTS" == 1 ]]; then
  python3 "$W/guard.py" mutate "$W/check" > "$W/gm.log" 2>&1 || { cat "$W/gm.log"; stop "Mutationstest $MK: eine Veraenderung wurde nicht erkannt"; }
  echo "OK $(grep -E '^Mutationstest' "$W/gm.log")"
  grep -q "UEBERSEHEN" "$W/gm.log" && { cat "$W/gm.log"; stop "Mutationstest enthaelt UEBERSEHEN"; }
fi
for py in "$SPY" "$VPY"; do
  for x in "$W/check"/*.py "$W/guard.py"; do
    "$py" -W error -c 'import sys; compile(open(sys.argv[1], encoding="utf-8").read(), sys.argv[1], "exec")' "$x" 2>"$W/pyc.log" || { cat "$W/pyc.log"; stop "py_compile $(basename "$x") mit $py"; }
  done
done
echo "OK py_compile ($SPY und $VPY)"
mod_import() {
  rm -rf "$W/try" && mkdir -p "$W/try"
  find "$DASH_DIR" -maxdepth 1 -name '*.py' -exec ln -s {} "$W/try/" \;
  rm -f "$W/try/ups_manager.py" "$W/try/lage_pages.py" "$W/try/prepper_docs.py"
  cp "$W/neu/ups_manager.py" "$W/neu/lage_pages.py" "$W/neu/prepper_docs.py" "$W/try/"
  slog="$W/imp-system.log"
  ( cd "$W/try" && PYTHONDONTWRITEBYTECODE=1 PYTHONNOUSERSITE=1 timeout 120 "$SPY" -c 'import ups_manager; print(ups_manager.selftest())' ) > "$slog" 2>&1 || { tail -n 40 "$slog"; stop "ups_manager-Selbsttest mit System-Python $SPY fehlgeschlagen"; }
  grep -q "ups_manager ok" "$slog" || { tail -n 20 "$slog"; stop "ups_manager-Selbsttest fehlt ($SPY)"; }
  if ( cd "$W/try" && PYTHONDONTWRITEBYTECODE=1 PYTHONNOUSERSITE=1 timeout 60 "$SPY" -c 'import dashboard' ) > "$W/spy-dash.log" 2>&1; then
    stop "System-Python konnte dashboard importieren. Das darf nicht die Pruefstrecke sein."
  fi
  vlog="$W/imp-venv.log"
  ( cd "$W/try" && PYTHONDONTWRITEBYTECODE=1 timeout 180 "$VPY" -c 'import dashboard' ) > "$vlog" 2>&1 || { tail -n 40 "$vlog"; stop "Import dashboard mit der Dashboard-venv $VPY fehlgeschlagen"; }
  grep -q "usvLesen aktiv:" "$vlog" || stop "USV-Selbsttest fehlt ($VPY)"
  grep -q "usvAlarm aktiv:" "$vlog" || stop "USV-Alarmtest fehlt ($VPY)"
  grep -q "pinnebergRolle aktiv:" "$vlog" || stop "Stufen-1-Anzeige fehlt ($VPY)"
  echo "OK System-Python ohne Flask: ups_manager. Dashboard-venv: Anzeige, Alarm und Stufe 1. Kein Geraet geoeffnet, nichts gesendet."
}
mod_import
PAGES=(/ /speicher /funk /pi /umwelt /funk433 /aprs /meteor /rundfunk /energie /dabhist /mesh /karte /lokale-energie)
APIS=(/api/sdr/ui /api/sdr/wd /api/br24 /api/sdr/sticktest /api/sdr/live /api/sdr/map /api/broadcast/events /api/t2/status /api/t3/status /api/t4/status /api/t4/map /api/t4/tii /api/meteor /api/sdr/status /api/usv /api/docs/list)
code() { local c; c=$("${CURL[@]}" "$@" -o /dev/null -w "%{http_code}" || true); [[ -z "$c" ]] && c=000; echo "$c"; }
code_r() { local c i; for i in 1 2 3 4 5; do c=$(code "$@"); [[ "$c" == 200 ]] && break; sleep "${C61_RETRY_S:-6}"; done; echo "$c"; }
declare -A PRE=()
for p in "${PAGES[@]}" "${APIS[@]}"; do PRE[$p]=$(code -L --max-redirs 5 "$B$p"); done
echo "vorher HTTP: $(for p in "${PAGES[@]}" "${APIS[@]}"; do printf '%s=%s ' "$p" "${PRE[$p]}"; done)"
ready_eg() {
  local limit="${C61_READY_S:-180}" pause t0 now elapsed line pyrc cf pf hc fc
  t0=$(date +%s)
  while true; do
    now=$(date +%s); elapsed=$((now - t0))
    if (( elapsed > limit )); then
      echo "FAIL nach ${elapsed}s keine EG-Seite" | tee -a "$W/eg-wait.log"
      return 1
    fi
    cf="$W/html/usv.json"; pf="$W/html/lokale.html"
    hc=$("${CURL[@]}" -o "$cf" -w "%{http_code}" "$B/api/usv" || true)
    fc=$("${CURL[@]}" -o "$pf" -w "%{http_code}" "$B/lokale-energie" || true)
    set +e
    line=$(python3 - "$cf" "$hc" "$pf" "$fc" << 'PY'
import json, sys
jp, jc, fp, fc = sys.argv[1:5]
def rd(p):
    try:
        return open(p, encoding="utf-8", errors="replace").read()
    except Exception:
        return ""
js, html = rd(jp), rd(fp)
hard = ("Traceback (most recent call last)", "jinja2.exceptions", "TemplateSyntaxError", "Internal Server Error")
hit = [s for s in hard if s in js or s in html]
if jc == "500" or fc == "500" or hit:
    print("FAIL HTTP %s/%s %s" % (jc, fc, ", ".join(hit) or "HTTP 500"))
    sys.exit(2)
if "Dashboard startet" in html or "Dashboard startet" in js:
    print("WAIT Startbildschirm")
    sys.exit(1)
if jc != "200" or fc != "200":
    print("WAIT HTTP %s/%s" % (jc, fc))
    sys.exit(1)
try:
    data = json.loads(js)
except Exception:
    print("WAIT JSON noch nicht lesbar")
    sys.exit(1)
if not isinstance(data, dict):
    print("FAIL JSON ist kein Objekt")
    sys.exit(2)
def bad(msg):
    print("FAIL " + msg)
    sys.exit(2)
if not isinstance(data.get("ok"), bool):
    bad("ok ist kein Wahrheitswert")
eg = data.get("eg")
if not isinstance(eg, dict):
    bad("eg fehlt")
if not isinstance(eg.get("ok"), bool) or not isinstance(eg.get("stale"), bool):
    bad("eg.ok oder eg.stale ist kein Wahrheitswert")
if eg.get("steuerung") is not False:
    bad("EG waere steuerbar")
soh = eg.get("soh")
if not isinstance(soh, dict) or soh.get("pct") is not None:
    bad("SoH ist nicht unbekannt")
akku = eg.get("akku")
if not isinstance(akku, dict) or akku.get("einbau") != "2026-05" or akku.get("wechsel") is not None:
    bad("EG-Einbau ist nicht 2026-05")
shut = eg.get("shutdown")
if not isinstance(shut, dict) or shut.get("aktiv") is not False:
    bad("EG-Abschaltung ist nicht aus")
if "20 %" in json.dumps(eg, ensure_ascii=False):
    bad("EG uebernimmt die Spitzboden-Abschaltung")
if eg.get("ok") is True and (eg.get("stale") is True or not isinstance(eg.get("charge"), (int, float))):
    bad("frische EG-Zeile ohne Ladung")
if "192.168.178.3" in html or "192.168.178.3" in js:
    bad("unbestaetigte Adresse in der Seite")
if 'id="usvEg"' not in html or "05.2026" not in html or 'id="usvEgShut"' not in html:
    bad("EG-Kachel fehlt auf der echten Seite")
print("READY HTTP 200 EG ok=%s Einbau 2026-05 SoH leer, Kachel da" % str(eg.get("ok")).lower())
sys.exit(0)
PY
)
    pyrc=$?
    set -e
    echo "$line" | tee -a "$W/eg-wait.log"
    if [[ "$pyrc" -eq 0 ]]; then echo "OK EG-Seite sichtbar nach ${elapsed}s"; return 0; fi
    if [[ "$pyrc" -eq 2 ]]; then return 2; fi
    pause="${C61_WAIT_S:-2}"; sleep "$pause"
  done
}
SVCS="prepper-dashboard prepper-sdr mesh-bridge mesh-bridge-bayern"
