  exit 0
fi
sudo -v || stop "sudo -v fehlgeschlagen (Passwort noetig?)"
waitd() { local i; for i in $(seq 1 80); do sleep "${C61_WAIT_S:-3}"; systemctl is-active --quiet prepper-dashboard && [[ "$(code "$B/")" == 200 ]] && return 0; done; return 1; }
rb() {
  set +e +o pipefail
  trap - ERR
  RB_DONE=1
  echo "ROLLBACK: $1"
  local x
  for x in "${INST[@]}"; do
    if [[ -f "$x.bak-$NM-$TS" ]]; then cp -a "$x.bak-$NM-$TS" "$x.rb" && mv -f "$x.rb" "$x"; fi
  done
  for x in "${INST[@]}"; do
    if [[ -f "$x.bak-$NM-$TS" ]]; then cmp -s "$x" "$x.bak-$NM-$TS" && echo "  $(basename "$x") = Sicherung" || echo "  WARNUNG $(basename "$x") ungleich Sicherung"; fi
  done
  if [[ "$RESTARTED" == 1 ]]; then sudo systemctl restart prepper-dashboard.service 9>&-; waitd; fi
  echo "alter Stand wieder aktiv: prepper-dashboard=$(systemctl is-active prepper-dashboard 2>/dev/null), HTTP / = $(code "$B/")"
  echo "  prepper-sdr wurde nicht neu gestartet; Tunnel, Firewall, Mesh und Paketquellen unveraendert; nichts gesendet"
}
