install_one() {
  local f="$1" x="$DASH_DIR/$f" src="$W/neu/$f"
  cp -a "$x" "$x.bak-$NM-$TS"
  cmp -s "$x" "$x.bak-$NM-$TS" || rbx "Sicherung $f ungleich Original"
  { ls -1t "$x.bak-$NM-"* 2>/dev/null || true; } | tail -n +$((KEEP_LAST + 1)) | while read -r o; do rm -f -- "$o"; done
  INST+=("$x")
  cp "$src" "$x.new"
  chmod --reference="$x.bak-$NM-$TS" "$x.new"
  mv -f "$x.new" "$x" || { rm -f "$x.new"; rbx "$f installieren"; }
}
for f in "${SINGLE[@]}"; do install_one "$f"; done
[[ "$(sfull "$DASH_DIR/ups_manager.py")" == "${NEU[ups_manager.py]}" ]] || rbx "ups_manager.py nach dem Kopieren falsch"
